mapper.select:
SELECT MESSAGE_MST_NO
FROM ${main_table}
WHERE ROWID IN (
    SELECT /*+ INDEX(TB_MESSAGE_SEND IDX_MESSAGE_SEND_03) */ ROWID
    FROM ${main_table}
    WHERE SEND_TYPE_CD IN (${flag_msg_type})
    AND MESSAGE_STATUS_CD = '00'
    AND ETRS_MTCD = '02'
    AND (SEND_EXPECTED_DT < TO_CHAR(SYSDATE, 'YYYYMMDD')
        OR (SEND_EXPECTED_DT = TO_CHAR(SYSDATE, 'YYYYMMDD') AND SEND_EXPECTED_TIME <= TO_CHAR(SYSDATE, 'HH24MISS'))
        ) ORDER BY REG_TYPE_CD , SEND_EXPECTED_DT, SEND_EXPECTED_TIME
    FETCH FIRST 500 ROWS ONLY
) ORDER BY REG_TYPE_CD , SEND_EXPECTED_DT, SEND_EXPECTED_TIME, REG_DT

SELECT MESSAGE_MST_NO
FROM ${main_table}
WHERE ROWID IN (
    SELECT /*+ INDEX(TB_MESSAGE_SEND IDX_MESSAGE_SEND_03) */ ROWID
    FROM ${main_table}
    WHERE SEND_TYPE_CD IN (${flag_msg_type})
      AND MESSAGE_STATUS_CD = '00'
      AND ETRS_MTCD = '01'
      AND (SEND_EXPECTED_DT < TO_CHAR(SYSDATE, 'YYYYMMDD')
        OR (SEND_EXPECTED_DT = TO_CHAR(SYSDATE, 'YYYYMMDD') AND SEND_EXPECTED_TIME <= TO_CHAR(SYSDATE, 'HH24MISS'))
        ) ORDER BY REG_TYPE_CD , SEND_EXPECTED_DT, SEND_EXPECTED_TIME
      FETCH FIRST 500 ROWS ONLY
) ORDER BY REG_TYPE_CD , SEND_EXPECTED_DT, SEND_EXPECTED_TIME, REG_DT

